  stroke:[{title:'2026 Guideline for the Early Management of Patients With Acute Ischemic Stroke',publisher:'American Heart Association/American Stroke Association',url:'https://www.ahajournals.org/doi/10.1161/STR.0000000000000513',accessedAt:'2026-11-11'}],
